package dev.infend.skyrimtext;
import java.util.*;
/** Original adaptation dialogue; not verbatim Skyrim dialogue. */
final class RoadDialogue {
    static final class Profile {
        final String speaker,opening,question,answer;
        Profile(String s,String o,String q,String a){speaker=s;opening=o;question=q;answer=a;}
    }
    private static final Map<String,Profile> DATA=new LinkedHashMap<>();
    private static void add(String id,String speaker,String opening,String question,String answer){DATA.put(id,new Profile(speaker,opening,question,answer));}
    static {
        add("maiq","М'Айк","М'Айк многое слышал о драконах. Но слышать и видеть совсем не одно и то же.","Что ты знаешь о драконах?","Люди говорят, что драконы любят золото. М'Айк думает, что они просто любят сидеть повыше.");
        add("bard","Талсгар","Путник! На этих дорогах хватает историй. Хочешь песню или рассказ?","Почему ты странствуешь?","В каждой деревне есть своя песня. Я собираю их, пока ноги носят меня.");
        add("bard_rest","Талсгар","Садись ближе к огню. Лютня уже настроена.","Какую песню ты знаешь?","О героях и драконах, о павших королях и о простых людях, которые остались верны себе.");
        add("courier","Курьер","Мне нужно успеть вручить письма. Заказчик не любит ждать.","Есть письма для меня?","Сегодня твоего имени в списке нет. Если появится письмо, я найду тебя.");
        add("other_courier","Гонец","Извини, это чужая корреспонденция. Мне велено не раскрывать адресата.","Куда ведёт твой путь?","К ближайшей таверне. Дальше дорога покажет.");
        add("hunter","Охотник","Тише. Здесь недавно прошёл олень, а за ним волчья стая.","Где безопаснее пройти?","Держись открытой дороги. В кустах у ручья замечены волки.");
        add("hunter_dog","Охотник","Мой пёс берёт след лучше любого следопыта.","Как давно вы охотитесь вместе?","Несколько зим. Когда зверь рядом, он всегда предупреждает меня.");
        add("mounted_hunter","Верховой охотник","На лошади легко пересечь равнины, но в лесу лучше идти пешком.","Что водится поблизости?","Олени на опушках, волки у оврагов. Если услышишь рык саблезуба, не подходи.");
        add("orc_hunters","Орочий охотник","Мы охотимся ради племени, а не ради славы.","Откуда вы пришли?","Из крепости. Вернёмся, когда добудем достаточно мяса.");
        add("vigilants","Дозорный Стендарра","Милость Стендарра всем праведным. Мы выслеживаем даэдра и тех, кто им служит.","Кого вы ищете?","Вампиров, даэдра, оборотней. Если заметишь следы, предупреди нас.");
        add("mage","Неудачливый маг","Я думал, что посох сделает меня великим магом. Пока он приносит одни неприятности.","Почему не учишься в Коллегии?","Меня не приняли. Пожалуй, магия не моё призвание.");
        add("college","Путник","Я добрался до Коллегии, но не сумел пройти испытание.","Что было на испытании?","Нужно было показать настоящее заклинание. Я растерялся и ушёл.");
        add("recruit_empire","Доброволец","Я иду в Солитьюд. Хочу вступить в легион и положить конец войне.","Почему именно легион?","Верю, что единство Империи позволит пережить угрозу Талмора.");
        add("recruit_storm","Доброволец","Держу путь в Виндхельм. Скайрим должен решать свою судьбу сам.","Почему ты выбрал Братьев Бури?","Хочу свободно чтить Талоса и защищать свой дом.");
        add("pilgrim","Фалдрус","Я направляюсь к святилищу Азуры. Её звезда укажет путь.","Где находится святилище?","В горах к югу от Винтерхолда. Статуя видна издалека.");
        add("bitten_hunter","Укушенный охотник","Меня укусили. Я боюсь, что уже заражён.","Где тебя настигли вампиры?","Недалеко от старого укрытия. Мне удалось уйти, но не без раны.");
        add("balbus","Балбус","Я собираю лучшие ингредиенты для Гурмана! Хотел бы когда-нибудь с ним встретиться.","Что ты собираешь?","Редкие травы и специи. Для великого повара только самое лучшее.");
        add("madwoman","Странная женщина","Они знают! Даже камни знают, куда мне идти.","Кто за тобой следит?","Не спрашивай. Слова могут услышать даже те, кого нет рядом.");
        add("giant_cow","Фермер","Мы раскрасили корову для великана. Может, он оставит нашу ферму в покое.","Почему корова раскрашена?","Так великаны поймут, что это дар, а не случайно заблудившийся скот.");
        add("wedding","Плаут Карван","Мы приглашены на свадьбу в Солитьюде. Надеюсь, успеем вовремя.","Кто женится?","Виттория Вичи и Асгейр Снежный Ходок. Говорят, это важный союз.");
        add("wedding_lost","Салония Карван","Мы сбились с дороги, а торжество уже прошло.","Что будете делать?","Попытаемся вернуться домой. Путешествие оказалось совсем не таким, как мы надеялись.");
        add("wedding_named","Салония Карван","Подарки целы, но от этих дорог у меня мурашки.","Расскажите о свадьбе.","Виттория Вичи выходит замуж за Асгейра. Наш охранник доведёт нас до Солитьюда.");
        add("afflicted","Страдающий","Периайт послал нам болезнь. Не подходи слишком близко.","Откуда ты пришёл?","Из Бтардамза. Если ищешь ответы, спроси у его святилища.");
        add("farmer_refugee","Путница","Я оставила всё позади. Не могу вернуться туда, откуда убежала.","Тебе нужна помощь?","Мне нужно добраться до поселения. Там я смогу найти крышу над головой.");
        add("adventurer","Искатель приключений","Слышал о старых руинах? Там может быть добыча, если не опередят другие.","Что ты ищешь?","Нечто ценное, чтобы потом не возвращаться на тяжёлую работу.");
        add("mercenary","Наёмник","Мне заплатили за то, чтобы проверить одно опасное место.","Можно узнать куда?","Заказ не для посторонних. Но советую держать оружие под рукой.");
        add("nobles","Знатный путник","У нас дела в столице. Надеюсь, дорога окажется спокойной.","Почему такая охрана?","Сейчас неспокойные времена. Мы предпочитаем не рисковать.");
        add("thalmor_patrol","Юстициар","По делам Доминиона. Не задерживай нас.","Что вы здесь делаете?","Наши поручения не касаются случайных путников.");
        add("skooma_dealer","Торговец","Ищешь что-нибудь особенное? Только говори тише.","Что ты продаёшь?","Товар не для стражи. Если не заинтересован, каждый пойдёт своей дорогой.");
        add("babette","Бабетта","Ты удивлён встретить меня здесь? Не все дела требуют присутствия в убежище.","Что ты делаешь ночью?","Иногда мне нужно поужинать. Лучше не задавай лишних вопросов.");
        add("namira","Почитатель Намиры","В смерти есть то, чего не понимают обычные люди.","Почему ты стоишь над телом?","У каждого свой взгляд на смерть. Намире известны секреты, от которых другие отворачиваются.");
        add("kynareth","Паломник","Я хочу увидеть Златолист. Давно не был в Вайтране.","Что значит это дерево?","Это святыня Кинарет, символ жизни и надежды.");
        add("mourning_forsworn","Изгой","Оставь нас. Мы прощаемся с павшим товарищем.","Могу ли я помочь?","Не нужно. Просто дай нам побыть здесь в тишине.");
        add("peddler","Торговец","Хороший день для дороги, если разбойники не испортят его.","Что у тебя в багаже?","Разные мелочи, ингредиенты и камни душ. Всё, что удаётся достать.");
        add("mistwatch","Беглянка","Я убежала из крепости. Там ещё держат людей!","Где находится крепость?","Туманная застава. Прошу, не оставляй их там.");
        add("letter_septimus","Гонец","Письмо от Септимия Сегония. Он просил передать лично.","Это связано с его исследованиями?","Мне не велено читать чужие письма. Прими его и реши сам.");
        add("letter_museum","Гонец","Приглашение в музей Данстара. Сил Весул надеется тебя увидеть.","Что за музей?","Говорят, посвящён Мифическому Рассвету. Остальное узнаешь на месте.");
        add("letter_brotherhood","Гонец","Письмо для тебя. Отправителя мне не назвали.","Как оно попало к тебе?","Мне заплатили за доставку. На этом моя роль заканчивается.");
        add("dawnguard_hunters","Охотник Стражи Рассвета","Мы разыскиваем кровопийц. Если ты не вампир, бояться нечего.","Как распознать вампира?","Следи за поведением и следами укусов. Не доверяй чужакам, которые появляются только ночью.");
        add("saliah","Салия","Страже нужны припасы. Я развожу распоряжения о тайниках.","Где искать запасы?","На севере. Записи помогут найти их, если дорога не оборвётся раньше.");
        add("dg_patrol","Боец Стражи Рассвета","Проверяем дороги. В последнее время вампиры стали смелее.","Как идёт охота?","Держимся вместе. Одному охотнику трудно пережить ночную засаду.");
        add("dg_scouts","Разведчик","Мы наблюдаем за Волкихаром. Не подходи к замку без причины.","Что вы заметили?","Движение у входа. Нам нужно доложить Израну.");
        add("island_elk","Охотник","Олени держатся северных лесов. Пепельные пустоши им не по нраву.","Что ещё водится на острове?","Нетчи, медведи и всякая живность, которую лучше обходить.");
        add("island_hunter_dog","Охотник Солстейма","Пёс чуяет разбойников за версту. На Солстейме это полезнее золота.","Где опаснее всего?","У пепельных троп и заброшенных лагерей. Держись ближе к поселениям.");
        add("island_hairy_hunter","Охотник","Есть те, для кого охота больше ремесла. Ты можешь встретить таких у Морозной Луны.","Кто такие охотники Морозной Луны?","Стая Маджни. Если хочешь узнать больше, найди их убежище.");
        add("island_reikling","Рьеклинг","Рьеклинг издаёт короткий воинственный крик и тычет копьём в сторону дороги.","Поблагодарить за помощь","Рьеклинг довольно подпрыгивает, затем исчезает среди камней.");
        add("student","Ученик мага","Я никак не справлюсь с защитным заклинанием. Ты можешь помочь?","Что не получается?","Сосредоточиться на защитной форме, а не на силе. Буду упражняться.");
        add("friend_gift","Знакомый путник","Помню твою помощь. Возьми это в благодарность.","Как твои дела?","Теперь всё лучше. Я не забываю тех, кто помог мне.");
        add("companion_aela","Эйла","Мы идём по следу зверя. Соратникам всегда хватает работы.","Как продвигается охота?","След свежий. Если не хочешь вмешиваться, держись в стороне.");
        add("dragon_aftermath","Уцелевший путник","Земля ещё горячая. Дракон пролетел совсем недавно.","Куда он улетел?","За горный хребет. Надеюсь, он не вернётся.");
        add("old_orc","Старый орк","Я достаточно прожил. Малакат ждёт меня, но я хочу достойной смерти.","Почему ты ищешь сражения?","Я не хочу умереть слабым и беспомощным. Пусть решит оружие.");
        add("assassin_other","Ассасин","Ты не тот, кого я ищу. Продолжай свой путь.","На кого заключён контракт?","Имя цели не твоё дело. У нас есть правила.");
        add("assassin_mistake","Ассасин","Описание совпадает. Назови себя, прежде чем я достану клинок.","Почему ты считаешь меня целью?","Заказчик дал приметы, но мог ошибиться. Докажи, что я не прав.");
        add("robber","Грабитель","Дорога платная. Отдавай кошель, и оба уйдём целыми.","Кто назначил такую плату?","Я. Если хочешь спорить, доставай оружие.");
        add("thief","Вор","Золото или жизнь. Выбирай быстро.","Что за манеры?","Я не хочу крови. Мне достаточно твоего кошелька.");
        add("false_imperials","Лжеофицер","По приказу легиона здесь взимается пошлина.","Покажи приказ легиона","Приказы не для простолюдинов. Плати, пока я не передумал.");
        add("imperial_prisoner","Имперский офицер","Пленный под стражей легиона. Не вмешивайся.","За что его задержали?","Он сражался на стороне мятежников. Решение примет командование.");
        add("storm_prisoner","Офицер Братьев Бури","Имперский солдат взят в плен. Мы отвечаем за него.","Куда вы его ведёте?","К нашим людям. Не вынуждай нас считать тебя врагом.");
        add("thalmor_prisoner","Юстициар","Этот человек подозревается в запрещённом поклонении Талосу.","Что с ним будет?","Его ждёт допрос. У тебя нет полномочий вмешиваться.");
        add("imperial_patrol","Имперский офицер","Патрулируем дорогу. Не мешай исполнению приказа.","Что слышно о войне?","Наши гарнизоны держатся. Но безопасной дороги теперь почти нет.");
        add("storm_patrol","Брат Бури","Мы охраняем родные земли. Держи глаза открытыми.","Что слышно о войне?","Легион стягивает силы. Северяне не собираются отступать.");
        add("deep_in_cups","Глубокий-в-Кубках","Помнишь ту шапку и пари? Теперь мне причитается плата.","Почему ты пришёл ко мне?","Я выполнил свою часть сделки. Теперь настала твоя очередь.");
        add("island_morgrul","Головорез Моргрула","Моргрул не любит, когда его деньги задерживают.","Кому предъявлен долг?","Мы получили приметы должника. Если это ошибка, объясняйся.");
    }
    static Profile find(String id){return DATA.get(id);}
    static int count(){return DATA.size();}
    static String line(Profile p,String text){return p.speaker+": «"+text+"»";}
}
